// Redis Stream consumer group worker
async function consumeTasks() {
  const results = await redis.xreadgroup('GROUP', 'workers', 'worker-1', 'COUNT', '10', 'BLOCK', '2000', 'STREAMS', 'tasks', '>');
  for (const [stream, entries] of results || []) {
    for (const [id, fields] of entries) {
      await processTask(id, fields);
      await redis.xack('tasks', 'workers', id);
    }
  }
}
